// Exemple minimal avec AWS SDK for JavaScript v3 : lister les buckets S3
// (nécessite des identifiants AWS valides avec les droits adéquats)
import { S3Client, ListBucketsCommand } from "@aws-sdk/client-s3";

const client = new S3Client({ region: "eu-west-3" });
const result = await client.send(new ListBucketsCommand({}));
console.log((result.Buckets ?? []).map((b) => b.Name));
